module app.main;
import std.task.{run,start,await,Scheduler};
import std.host.command.{command,read,CommandEvent};
import std.host.command.start as spawn;
import std.fs.{Region,path,atomic_replace};
import std.fs.IOError as FileError;
import std.effects.Fs;
import std.io.{println,read_line,IOError};
import std.text.from_usize;
import std.codec.text.utf8_encode;
import std.collections.len;
type State;
impl State ~ Region;
flow save(name:string,value:bytes)->unit {
 let location=match path<State>(name) { Ok(value)=>value,Err(_)=>{abort("invalid fixture path");} };
 atomic_replace(location,value);
}
flow main(args:Array<string>)->i32 ![Async,Console,Command.start<DefaultCommandSandbox>,Command.read<DefaultCommandSandbox>,Fs.atomic_replace<State>,Error<FileError>,Error<IOError>] {
 return run((scheduler:Scheduler)=> {
  let process=spawn(command("/usr/bin/python3",["-u","-c","import sys,time\nblock=('鹈鹕 café\\n'*4096).encode()\nfor _ in range(48):\n sys.stdout.buffer.write(block); sys.stdout.buffer.flush(); time.sleep(0.02)"]),DefaultCommandSandbox);
  let reader=start(()=> {
   var count:usize=0;
   var index:usize=0;
   while true limit Iterations(2147483647) {
    let result=read(process,65536);
    match result {
     CommandEvent.Output(output,error)=>{save("chunk-"+from_usize(index),output);count=count+len(output);},
     CommandEvent.Exited(code,output,error)=>{save("chunk-"+from_usize(index),output);count=count+len(output);save("done",utf8_encode(from_usize(count)));return code;},
     CommandEvent.Stopped(output,error)=>{abort("fixture producer stopped");}
    }
    index=index+1;
   }
   return 0;
  });
  println("WAIT_INPUT");
  let input=read_line();
  println("ACK "+input);
  return await(reader);
 });
}
